```javascript
// resolvers.js
const prisma = require('../prisma');

exports.createOrder = async (parent, { userId, products, total }) => {
  const product = await prisma.product.create({
    data: {
      name: 'New Product',
      price: 10.99,
    },
  });

  const order = await prisma.order.create({
    data: {
      userId,
      products,
      total,
    },
  });

  return order;
};

exports.updateOrder = async (parent, { id, userId, products, total }) => {
  const order = await prisma.order.findUnique({ where: { id }, select: { userId, products, total } });

  if (!order) {
    throw new Error('Order not found');
  }

  if (userId !== order.userId) {
    throw new Error('User is not the owner of the order');
  }

  order.products = products;
  order.total = total;

  await prisma.order.update({ where: { id }, data: { products, total } });

  return order;
};

exports.deleteOrder = async (parent, { id }) => {
  const order = await prisma.order.findUnique({ where: { id }, select: { userId, products, total } });

  if (!order) {
    throw new Error('Order not found');
  }

  if (userId !== order.userId) {
    throw new Error('User is not the owner of the order');
  }

  await prisma.order.delete({ where: { id } });

  return null;
};
```

