def create_product():
    new_product = Product(len(products) + 1, 'Product {}'.format(len(products) + 1), 19.99, 'This is product {}'.format(len(products) + 1))
    products.append(new_product)
    return jsonify(new_product.to_dict()), 201

# PUT /products/{id}
