  const bookIndex = books.findIndex((b) => b.id === id);
  if (bookIndex === -1) {
    res.status(404).send({ error: 'Book not found' });
  } else {
    books.splice(bookIndex, 1);
    res.json({ message: 'Book deleted successfully' });
  }
});

const port = 3000;
app.listen(port, () => {
  console.log(`Server started on port ${port}`);
});
```
